INSERT INTO _s495_1_enoch_m VALUES
('1-enoch-11-windows-of-heaven-open-truth-and-peace-joined',11,1,'canon','deuteronomy',28,12,1,$n$Deuteronomy 28:12 — *Yahuah (LORD) shall open unto thee his good treasure, the heaven to give the rain unto thy land in his season, and to bless all the work of thine hand: and thou shalt lend unto many nations, and thou shalt not borrow.* Moses promises the same opened treasure of heaven.$n$),
('1-enoch-11-windows-of-heaven-open-truth-and-peace-joined',11,1,'canon','malachi',3,10,2,$n$Malachi 3:10 — *Bring ye all the tithes into the storehouse, that there may be meat in mine house, and prove me now herewith, saith Yahuah Tseva'ot (LORD of hosts), if I will not open you the windows of heaven, and pour you out a blessing, that there shall not be room enough to receive it.* Malachi hears of the same windows of heaven opened.$n$),
('1-enoch-11-windows-of-heaven-open-truth-and-peace-joined',11,2,'canon','psalms',85,10,3,$n$Psalm 85:10 — *Mercy and truth are met together; righteousness and peace have kissed each other.* The psalmist sees truth and peace joined as Enoch does.$n$),
('1-enoch-28-wilderness-planted-and-watered-by-yahuah',28,1,'canon','isaiah',41,19,1,$n$Isaiah 41:19 — *I will plant in the wilderness the cedar, the shittah tree, and the myrtle, and the oil tree; I will set in the desert the fir tree, and the pine, and the box tree together:* Isaiah promises trees planted in the wilderness.$n$),
('1-enoch-28-wilderness-planted-and-watered-by-yahuah',28,2,'canon','isaiah',35,6,2,$n$Isaiah 35:6 — *Then shall the lame man leap as an hart, and the tongue of the dumb sing: for in the wilderness shall waters break out, and streams in the desert.* Isaiah promises the same waters in the desert.$n$),
('1-enoch-28-wilderness-planted-and-watered-by-yahuah',28,3,'canon','genesis',2,6,3,$n$Genesis 2:6 — *But there went up a mist from the earth, and watered the whole face of the ground.* The first watering of the ground rose from the earth as Enoch sees.$n$),
('1-enoch-68-michael-will-not-take-their-part',68,5,'canon','jude',1,6,1,$n$Jude 1:6 — *And the angels which kept not their first estate, but left their own habitation, he hath reserved in everlasting chains under darkness unto the judgment of the great day.* Jude gives the same everlasting judgement on the angels who left their place.$n$),
('1-enoch-68-michael-will-not-take-their-part',68,4,'canon','isaiah',14,14,2,$n$Isaiah 14:14 — *I will ascend above the heights of the clouds; I will be like the El Elyon (most High).* The pride that Michael refuses to excuse is named in the prophet's own words.$n$),
('1-enoch-68-michael-will-not-take-their-part',68,2,'canon','jude',1,9,3,$n$Jude 1:9 — *Yet Michael the archangel, when contending with the devil he disputed about the body of Moses, durst not bring against him a railing accusation, but said, Yahuah (Lord) rebuke thee.* Jude shows Michael leaving the rebuke with Yahuah.$n$),
('1-enoch-86-stars-fall-and-the-cattle-bear-giants',86,1,'canon','isaiah',14,12,1,$n$Isaiah 14:12 — *How art thou fallen from heaven, O Lucifer, son of the morning! how art thou cut down to the ground, which didst weaken the nations!* The prophet asks the same question of a bright one fallen to the earth.$n$),
('1-enoch-86-stars-fall-and-the-cattle-bear-giants',86,3,'canon','genesis',6,2,2,$n$Genesis 6:2 — *That the sons of Elohim (God) saw the daughters of men that they were fair; and they took them wives of all which they chose.* Genesis tells in one line what the dream shows in the descent of the stars.$n$),
('1-enoch-86-stars-fall-and-the-cattle-bear-giants',86,4,'canon','genesis',6,4,3,$n$Genesis 6:4 — *There were giants in the earth in those days; and also after that, when the sons of Elohim (God) came in unto the daughters of men, and they bare children to them, the same became mighty men which were of old, men of renown.* Genesis names the children that the dream pictures as beasts.$n$),
('1-enoch-86-stars-fall-and-the-cattle-bear-giants',86,6,'canon','genesis',6,11,4,$n$Genesis 6:11 — *The earth also was corrupt before Elohim (God), and the earth was filled with violence.* The terror in the dream is the violence that Genesis says filled the earth.$n$),
('1-enoch-91-apocalypse-of-weeks-judgement-house-and-new-heaven',91,7,'canon','isaiah',26,21,1,$n$Isaiah 26:21 — *For, behold, Yahuah (LORD) cometh out of his place to punish the inhabitants of the earth for their iniquity: the earth also shall disclose her blood, and shall no more cover her slain.* Isaiah sees the same coming of Yahuah to judge the earth.$n$),
('1-enoch-91-apocalypse-of-weeks-judgement-house-and-new-heaven',91,10,'canon','daniel',12,2,2,$n$Daniel 12:2 — *And many of them that sleep in the dust of the earth shall awake, some to everlasting life, and some to shame and everlasting contempt.* Daniel sees the same sleepers wake.$n$),
('1-enoch-91-apocalypse-of-weeks-judgement-house-and-new-heaven',91,13,'canon','haggai',2,9,3,$n$Haggai 2:9 — *The glory of this latter house shall be greater than of the former, saith Yahuah Tseva'ot (LORD of hosts): and in this place will I give peace, saith Yahuah Tseva'ot (LORD of hosts).* Haggai hears of the same latter house, greater than the former.$n$),
('1-enoch-91-apocalypse-of-weeks-judgement-house-and-new-heaven',91,16,'canon','isaiah',65,17,4,$n$Isaiah 65:17 — *For, behold, I create new heavens and a new earth: and the former shall not be remembered, nor come into mind.* Isaiah hears of the same new heavens and new earth.$n$),
('1-enoch-101-sea-and-sky-teach-the-fear-of-the-most-high',101,1,'canon','isaiah',40,26,1,$n$Isaiah 40:26 — *Lift up your eyes on high, and behold who hath created these things, that bringeth out their host by number: he calleth them all by names by the greatness of his might, for that he is strong in power; not one faileth.* Isaiah sends the people to look at the heavens and see who made them.$n$),
('1-enoch-101-sea-and-sky-teach-the-fear-of-the-most-high',101,2,'canon','deuteronomy',11,17,2,$n$Deuteronomy 11:17 — *And then the LORD’S wrath be kindled against you, and he shut up the heaven, that there be no rain, and that the land yield not her fruit; and lest ye perish quickly from off the good land which Yahuah (LORD) giveth you.* Moses had already named the shut heaven as the answer to turning from the commandments.$n$),
('1-enoch-101-sea-and-sky-teach-the-fear-of-the-most-high',101,6,'canon','jeremiah',5,22,3,$n$Jeremiah 5:22 — *Fear ye not me? saith Yahuah (LORD): will ye not tremble at my presence, which have placed the sand for the bound of the sea by a perpetual decree, that it cannot pass it: and though the waves thereof toss themselves, yet can they not prevail; though they roar, yet can they not pass over it?* Jeremiah points to the sand that bounds the sea as the sign to fear Yahuah.$n$),
('1-enoch-101-sea-and-sky-teach-the-fear-of-the-most-high',101,4,'canon','psalms',107,26,4,$n$Psalm 107:26 — *They mount up to the heaven, they go down again to the depths: their soul is melted because of trouble.* The psalmist pictures the same trouble of men in ships on the sea.$n$),
('1-enoch-105-shine-as-the-lights-of-heaven',105,1,'canon','daniel',12,3,1,$n$Daniel 12:3 — *And they that be wise shall shine as the brightness of the firmament; and they that turn many to righteousness as the stars for ever and ever.* Daniel names those who turn many to righteousness as the guides who shine.$n$),
('1-enoch-105-shine-as-the-lights-of-heaven',105,1,'canon','ezekiel',3,17,2,$n$Ezekiel 3:17 — *Son of Adam, I have made thee a watchman unto the house of Yashar'el (Israel): therefore hear the word at my mouth, and give them warning from me.* Ezekiel is made a watchman to give warning from the mouth of Yahuah.$n$),
('1-enoch-105-most-high-arises-in-wrath',105,2,'canon','isaiah',32,17,1,$n$Isaiah 32:17 — *And the work of righteousness shall be peace; and the effect of righteousness quietness and assurance for ever.* Isaiah says peace is the work of righteousness.$n$),
('1-enoch-105-names-known-memorial',105,2,'canon','john',14,23,4,$n$John 14:23 — *Yahusha (Jesus) answered and said unto him, If a man love me, he will keep my words: and my Father will love him, and we will come unto him, and make our abode with him.* Yahusha says the nearness is for the one who keeps his words.$n$),
('1-enoch-105-righteous-inherit-the-earth',105,1,'canon','psalms',37,9,1,$n$Psalm 37:9 — *those that wait upon Yahuah (LORD), they shall inherit the earth.* The psalm names who is left holding the earth.$n$),
('1-enoch-106-the-birth-of-noah-and-the-seed-kept-through-the-flood',106,14,'canon','genesis',6,2,1,$n$Genesis 6:2 — *That the sons of Elohim (God) saw the daughters of men that they were fair; and they took them wives of all which they chose.* Genesis gives the transgression that Enoch tells Methuselah of.$n$),
('1-enoch-106-the-birth-of-noah-and-the-seed-kept-through-the-flood',106,17,'canon','genesis',6,4,2,$n$Genesis 6:4 — *There were giants in the earth in those days; and also after that, when the sons of Elohim (God) came in unto the daughters of men, and they bare children to them, the same became mighty men which were of old, men of renown.* Genesis names the giants Enoch foretells.$n$),
('1-enoch-106-the-birth-of-noah-and-the-seed-kept-through-the-flood',106,18,'canon','genesis',7,23,3,$n$Genesis 7:23 — *And every living substance was destroyed which was upon the face of the ground, both man, and cattle, and the creeping things, and the fowl of the heaven; and they were destroyed from the earth: and Noah only remained alive, and they that were with him in the ark.* Genesis records that Noah only remained alive with those in the ark.$n$),
('1-enoch-106-the-birth-of-noah-and-the-seed-kept-through-the-flood',106,16,'canon','1-peter',3,20,4,$n$1 Peter 3:20 — *Which sometime were disobedient, when once the longsuffering of Elohim (God) waited in the days of Noah, while the ark was a preparing, wherein few, that is, eight souls were saved by water.* Peter counts the souls saved through the water.$n$),
('1-enoch-107-plant-of-righteousness-remnant',107,1,'canon','psalms',24,6,1,$n$Psalm 24:6 — *This is the generation of them that seek him, that seek thy face, O Jacob. Selah.* The psalmist names the generation that seeks Yahuah.$n$),
('1-enoch-107-plant-of-righteousness-remnant',107,1,'canon','daniel',9,24,2,$n$Daniel 9:24 — *Seventy weeks are determined upon thy people and upon thy holy city, to finish the transgression, and to make an end of sins, and to make reconciliation for iniquity, and to bring in everlasting righteousness, and to seal up the vision and prophecy, and to anoint the most Holy.* Daniel hears of the end of transgression and sin.$n$),
('1-enoch-107-this-one-shall-comfort-us',107,3,'canon','genesis',5,29,1,$n$Genesis 5:29 — *And he called his name Noah, saying, This same shall comfort us concerning our work and toil of our hands, because of the ground which Yahuah (LORD) hath cursed.* Lamech names his son for comfort over the cursed ground.$n$),
('1-enoch-107-this-one-shall-comfort-us',107,3,'canon','genesis',8,21,2,$n$Genesis 8:21 — *And Yahuah (LORD) smelled a sweet savour; and Yahuah (LORD) said in his heart, I will not again curse the ground any more for man’s sake; for the imagination of man’s heart is evil from his youth; neither will I again smite any more every thing living, as I have done.* The comfort in the name came true when Yahuah would not again curse the ground.$n$),
('1-enoch-107-noah-sign-of-salvation',107,2,'canon','genesis',5,28,1,$n$Genesis 5:28 — *And Lamech lived an hundred eighty and two years, and begat a son:* The plain record of the birth that Enoch confirms is true.$n$),
('1-enoch-107-watchers-violence-judgment',107,1,'canon','genesis',6,11,1,$n$Genesis 6:11 — *the earth was filled with violence.* Genesis gives the same verdict over the same earth.$n$);
CREATE TEMP TABLE _s495_1_enoch_j (slug TEXT) ON COMMIT DROP;
INSERT INTO _s495_1_enoch_j VALUES
('1-enoch-105-most-high-arises-in-wrath'),
('1-enoch-105-names-known-memorial'),
('1-enoch-105-righteous-inherit-the-earth'),
('1-enoch-105-shine-as-the-lights-of-heaven'),
